INSERT INTO topic (id, code, name, description, icon, sort_order, builtin) VALUES (11, 'cloud', '云计算', '云产品与云上架构运维（VPC/OSS/CDN/RDS/负载均衡/弹性/安全/成本/IaC）', 'Cloud', 11, 1);

INSERT INTO question (topic_id, type, difficulty, title, content, options, answer, follow_ups, tags, frequency, position_codes, source) VALUES
(11, 'CHOICE', 1, '用户只管写代码、平台负责运行环境的云服务模式属于？', NULL, '[\"A. IaaS\",\"B. PaaS\",\"C. SaaS\",\"D. FaaS 不是\"]', 'A 不对——这是 PaaS（平台即服务）：提供运行时/数据库/中间件，用户不管OS。IaaS 给到虚拟机层面；SaaS 是直接用软件。', NULL, '[\"概念\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 1, 'ECS（云服务器）属于哪种服务模式？', NULL, '[\"A. IaaS\",\"B. PaaS\",\"C. SaaS\",\"D. 私有云专属\"]', 'A。云主机是最典型的 IaaS：给计算资源，OS 以上归用户管。', NULL, '[\"概念\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 1, '公有云与私有云的本质区别？', NULL, '[\"A. 谁运营与资源共享池不同（公有云多租户共享，私有云专属）\",\"B. 性能不同\",\"C. 价格不同\",\"D. 技术不同\"]', 'A。混合云=两者组合+统一管理。社区云/专有云为衍生形态。', NULL, '[\"概念\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'Region 与 Availability Zone（可用区）的关系？', NULL, '[\"A. 一个 Region 包含多个物理隔离的 AZ\",\"B. 相同概念\",\"C. AZ 包含多个 Region\",\"D. 无关\"]', 'A。高可用设计基线：同 Region 跨 AZ 部署（延迟低且容机房级故障）；跨 Region 容灾成本高延迟大。', NULL, '[\"架构\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '责任共担模型（Shared Responsibility）中用户负责什么？', NULL, '[\"A. 物理机房\",\"B. 云上安全：系统补丁/账号权限/应用与数据安全\",\"C. 宿主机硬件\",\"D. 全部\"]', 'B。云厂商负责"云的安全"（基础设施），用户负责"云中安全"（配置与数据）——配置泄露是用户侧责任。', NULL, '[\"安全\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '包年包月、按量付费、抢占式（竞价）实例的选择？', NULL, '[\"A. 稳定长期=包年包月；波动=按量；可中断批任务=抢占式（1-2折）\",\"B. 全按量最省\",\"C. 全包月\",\"D. 无差别\"]', 'A。混合策略：基线用包月/预留，峰值按量，离线任务竞价+被回收重试。', NULL, '[\"成本\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '按量付费实例的"节省停机模式"省钱前提是？', NULL, '[\"A. 停机不收费但云盘/EIP/带宽仍计费\",\"B. 全免费\",\"C. 只有CPU免费\",\"D. 无此模式\"]', 'A。停机释放计算资源，但存储与弹性IP照收——账单排查常见误解。', NULL, '[\"成本\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '安全组（Security Group）本质是？', NULL, '[\"A. 虚拟防火墙（有状态，作用于ECS实例级）\",\"B. 物理防火墙\",\"C. 负载均衡\",\"D. 账号权限\"]', 'A。有状态：入站放行的连接，响应流量自动放回。网络ACL是无状态的子网级过滤。', NULL, '[\"网络\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '安全组规则默认策略与最佳实践？', NULL, '[\"A. 默认拒绝，按需白名单放行（最小开放）\",\"B. 全放行再封\",\"C. 只开22/3389\",\"D. 无所谓\"]', 'A。经典错误：0.0.0.0/0 开 22/3306/6379——公网爆破与勒索主因。', NULL, '[\"安全\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'VPC 之间默认网络是否互通？', NULL, '[\"A. 隔离，需对等连接/云企业网/专线打通\",\"B. 同账号互通\",\"C. 同Region互通\",\"D. 全通\"]', 'A。VPC 是逻辑隔离的二层网络——"连不上先想到是不同VPC"。', NULL, '[\"网络\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '弹性公网 IP（EIP）与普通公网 IP 的区别？', NULL, '[\"A. EIP 可独立申请、解绑重绑到其他实例\",\"B. 无区别\",\"C. EIP更贵必用\",\"D. 普通IP可迁移\"]', 'A。故障切换：把 EIP 从坏实例秒绑到备实例。普通公网IP与实例绑定生命周期，释放即失。', NULL, '[\"网络\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '多台无公网 IP 的内网机器访问公网，用什么？', NULL, '[\"A. NAT 网关（SNAT）\",\"B. EIP挨个绑\",\"C. 安全组\",\"D. VPN\"]', 'A。SNAT 共享出口；DNAT 反向做端口发布（类似路由器端口映射）。', NULL, '[\"网络\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 3, '跨 VPC 大带宽内网互通（生产级）首选？', NULL, '[\"A. 对等连接/云企业网（内网互通）\",\"B. 公网+安全组\",\"C. VPN加密隧道（带宽小延迟大）\",\"D. 跳板机\"]', 'A。VPN 适合临时/分支小流量；专线/高速通道用于混合云大带宽低延迟。', NULL, '[\"网络\",\"架构\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 1, '对象存储（OSS/S3/COS）的三个特征？', NULL, '[\"A. 海量容量/按量付费/HTTP API扁平命名（bucket+key）\",\"B. 目录树结构\",\"C. 只能存文本\",\"D. 需要挂载\"]', 'A。没有真正的目录（是key前缀模拟）；适合静态资源/备份/日志归档，不适合随机改写的DB场景。', NULL, '[\"存储\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'OSS 存储类别从热到冷排序？', NULL, '[\"A. 标准 → 低频访问 → 归档 → 冷归档\",\"B. 归档最贵\",\"C. 低频最便宜\",\"D. 无差别\"]', 'A。越冷越便宜但取回越慢越贵（归档取回要解冻分钟级）——按访问频率选型。', NULL, '[\"存储\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '备份文件 30 天后自动转归档、180天删除，用什么实现？', NULL, '[\"A. 生命周期规则（Lifecycle）\",\"B. 手动脚本 only\",\"C. 跨域复制\",\"D. 版本控制\"]', 'A。规则引擎自动化冷热分层，是存储成本治理的第一手段。', NULL, '[\"存储\",\"成本\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '云盘快照（Snapshot）的正确认知？', NULL, '[\"A. 某时刻云盘的增量备份，可回滚/建新盘\",\"B. 实时镜像\",\"C. 替代备份策略\",\"D. 免费无限\"]', 'A。快照≠备份体系全部：跨Region复制快照+定期演练才是容灾姿势；快照本身按量计费。', NULL, '[\"存储\",\"备份\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '数据库场景应选哪类云盘？', NULL, '[\"A. ESSD/SSD 云盘（高IOPS低延迟）\",\"B. 普通高效云盘\",\"C. 对象存储挂载\",\"D. NAS\"]', 'A。云盘类型按 IOPS/吞吐选；DB 还要考虑与实例规格的 IOPS 上限匹配。', NULL, '[\"存储\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '网站静态资源加速分发的标准方案？', NULL, '[\"A. OSS 存储源 + CDN 边缘分发\",\"B. ECS 自建 nginx only\",\"C. 网盘链接\",\"D. 数据库存文件\"]', 'A。配合回源鉴权（防绕过）+ 缓存策略；动态请求不走CDN。', NULL, '[\"CDN\",\"架构\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'CDN"回源"指？', NULL, '[\"A. 边缘节点未命中/过期时到源站取内容\",\"B. 用户上传\",\"C. DNS解析\",\"D. 证书更新\"]', 'A。回源率低=命中率好；回源风暴（缓存同时过期）要靠预热与分级TTL防。', NULL, '[\"CDN\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '防止他人盗用 OSS/CDN 资源（流量被刷）的手段？', NULL, '[\"A. Referer 防盗链+URL签名（鉴权URL）+限额告警\",\"B. 改文件名\",\"C. 无办法\",\"D. 删除文件\"]', 'A。配合 CDN 用量封顶与异常告警——被刷一晚上账单五位数是真实事故。', NULL, '[\"CDN\",\"安全\",\"成本\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'ECS 元数据（Metadata）的正确用法与风险？', NULL, '[\"A. 实例内 100.100.100.200 获取自身信息/临时凭证；SSRF 漏洞可窃取\",\"B. 纯无害\",\"C. 只能管理员用\",\"D. 已废弃\"]', 'A。经典攻击：应用 SSRF 读元数据拿 STS 凭证 → 打穿云资源。加固：加固模式+禁用旧接口。', NULL, '[\"安全\",\"进阶\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '镜像（Image）在云上的最佳实践？', NULL, '[\"A. 自定义镜像固化基线（补丁+agent+安全配置），启动即合规\",\"B. 裸机开机手装\",\"C. 公共镜像就够\",\"D. 每次快照当镜像\"]', 'A。配合实例启动脚本（user data）/云助手做差异化配置——不可变基础设施思路。', NULL, '[\"运维\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 3, '云企业网（CEN）/对等连接 vs VPN 网关的选型？', NULL, '[\"A. CEN/对等：内网级带宽延迟（生产互连）；VPN：加密隧道走公网（临时/分支）\",\"B. VPN更快\",\"C. 无区别\",\"D. 只能VPN\"]', 'A。混合云主线：专线+CEN 组网，VPN 作备份链路。', NULL, '[\"网络\",\"进阶\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 1, '企业为什么上云？说 3 个理由与 1 个顾虑。', NULL, NULL, '理由：1) 弹性（分钟级扩容应对流量波峰，不用为峰值囤硬件）2) 免运维硬件（机房/供电/硬件故障由厂商兜底）3) 全球部署与丰富托管服务（DB/缓存/AI 开箱即用）。顾虑：数据安全与合规、被锁定（lock-in）、成本失控风险——对应答出"混合云+治理"即成熟。', NULL, '[\"概念\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '设计一个生产环境 VPC 网段与子网划分。', NULL, NULL, '示例：VPC 10.0.0.0/16；交换机按 AZ×层次拆：
- 公网子网 /24（LB）：10.0.1.0/24、10.0.2.0/24（双AZ）
- 应用子网 /24：10.0.11.0/24、10.0.12.0/24
- 数据子网 /24：10.0.21.0/24、10.0.22.0/24（无公网路由）
要点：预留地址空间（业务增长）、多AZ对称、网段不与本地IDC重叠（混合云前提）、数据层不暴露公网。', NULL, '[\"网络\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '安全组变更把自己 SSH 锁外面的自救？', NULL, NULL, '云控制台/VNC 控制台不依赖 SSH——登录控制台改安全组放行 22（限自己IP）。预防：1) 改安全组前开第二条规则"保命IP"2) 用云厂商的运维编排/定时回滚任务 3) 变更窗口双人复核。"先留后路再动手"是网络变更铁律。', NULL, '[\"安全\",\"实战\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '如何把本地 100GB 文件高效传入 OSS？', NULL, NULL, '1. ossutil 分片并行上传（大文件自动 Multipart，断点续传）
2. 内网走内网 Endpoint（免公网流量费且快）
3. 超大数据量用闪电立方/离线迁移
4. 传后校验 CRC/MD5
要点：内网 endpoint 与公网 endpoint 的费用差。', NULL, '[\"存储\",\"实战\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '云主机磁盘满了，云盘扩容的正确步骤？', NULL, NULL, '1. 控制台/快照先备份（快照）
2. 云盘扩容（在线扩容支持大多数场景）
3. **系统内扩展分区与文件系统**：growpart + resize2fs（ext4）/ xfs_growfs（xfs）——只扩盘不扩文件系统是新手必踩坑
4. 数据盘同理；Windows 用磁盘管理扩展卷
5. 验证 df -h', NULL, '[\"存储\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 3, '混合云架构中，哪些业务适合放云上、哪些留本地？', NULL, NULL, '云上：面向互联网的应用（弹性）、新业务试点（快速搭建）、大数据/AI（弹性算力）、灾备（按需成本低）。
本地：强合规数据（未脱敏核心数据）、极低延迟的制造控制、已有大量沉没资产的稳定核心系统。
关键：统一身份/网络（专线）/监控打通，别变成两套孤岛。', NULL, '[\"架构\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '云上成本优化的系统打法（至少5条）。', NULL, NULL, '1. 计费模式匹配：稳态包月/预留实例+峰值按量+离线竞价
2. 闲置治理：未挂载云盘/闲置EIP/空载实例清理（月度报告）
3. 存储分层：生命周期规则自动转低频/归档
4. 带宽策略：CDN卸载静态流量、闲时带宽
5. 标签化分账：按项目/团队核算，预算告警
6. 规格右尺：CPU长期<20% 降配
成本是持续性治理不是一次性运动。', NULL, '[\"成本\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 3, '什么是云上"不可变基础设施"实践？', NULL, NULL, '实例/环境不原地修改：改镜像→重新拉起替换（配合弹性伸缩/镜像版本）。好处：环境漂移消失、故障替换快、审计清晰（每个实例来自哪个镜像版本）。配套：user data/cloud-init 注入差异配置、实例无状态化（数据出盘）。与容器理念同源。', NULL, '[\"架构\",\"素养\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '从 ECS 角度解释"重启"与"停止再启动"的区别？', NULL, NULL, '重启（Reboot）：同一台物理宿主机上重启系统，IP不变。
停止再启动（按量+节省模式）：实例可能迁移到别的宿主机，按量实例可省计算费；普通公网IP可能变化（EIP不变）。
运维含义：**不要依赖实例的物理唯一性**——云上一切按"随时会被替换"设计。', NULL, '[\"计算\",\"素养\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 3, '早上发现 OSS 账单暴涨 2 万元（一夜之间），怎么处置？', '怀疑资源被恶意刷流量。', NULL, '1. 止血优先：CDN/OSS 开启用量封顶（带宽/流量阈值自动停服，评估业务取舍）；更换被刷的 Bucket 域名或下线盗链资源
2. 定位：访问日志分析——Referer/UA/IP 分布、Top URL；确认是盗链还是被枚举
3. 加固：Referer 白名单+URL签名（防盗链）、CDN 鉴权、私读 Bucket+STS 临时凭证
4. 追损：工单申请恶意流量费用减免（提供证据）
5. 预防：用量异动告警（小时级）、成本预算告警、密钥轮换（可能 AK 泄漏）', NULL, '[\"应急\",\"成本\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 2, '某 ECS 被 SSH 爆破并植入挖矿程序，云上处置流程？', NULL, NULL, '1. 隔离：安全组改为只留管理IP、或换安全组到隔离组（阻断外连矿池）
2. 取证：last/进程/计划任务/启动项，定位入侵路径（弱口令？0day？AK泄漏？）
3. 处置：重置系统（可信镜像重装）优于杀毒式清理（Rootkit 不可信）
4. 加固：改密钥登录、安全组收紧、安装云安全中心、补丁基线镜像化
5. 复盘：为什么告警晚了（云监控/安全中心阈值）
核心：**重装>清杀**，云上重建成本低。', NULL, '[\"安全\",\"应急\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 2, '业务要求"机房级故障不影响服务"，云上怎么落地？', NULL, NULL, '1. 同 Region 双 AZ 部署：LB/应用跨AZ、数据库用云厂商多可用区高可用版（RDS 主备跨AZ）
2. 数据层：跨AZ同步复制；快照跨AZ/Region 复制
3. 演练：禁用单AZ流量验证自动切换（沙箱环境）
4. 更高级：单元化跨 Region 双活（成本高，按业务分级）
5. 依赖检查：消息队列/缓存也跨AZ
答题层次：先双AZ起步，再谈跨Region，别一上来吹异地多活。', NULL, '[\"架构\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 2, '用户反馈大文件下载很慢（海外/跨运营商），怎么优化？', NULL, NULL, '1. 定位：是源站慢（ECS带宽跑满）还是传输路径慢（跨网/跨境）
2. 方案：静态资源上 CDN（就近边缘节点）；大文件开启传输加速（付费）或分片并行下载（Range）
3. OSS 直传：生成签名 URL 卸载 ECS 带宽
4. 协议：支持 HTTP/2 或换 QUIC 减弱丢包影响
5. 观测：CDN 实时日志+命中率
考点：区分"带宽不够"与"路径远"。', NULL, '[\"CDN\",\"实战\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 3, '突发活动流量 10 倍增长，设计应对方案。', NULL, NULL, '1. 预估容量：按压测单机容量×峰值需求，提前扩容（包月买不长租，活动后退）
2. 弹性：ESS 定时任务（活动开始前预扩）+ 动态弹性（CPU/QPS 触发）兜底
3. 卸载：静态上CDN、读写分离、缓存预热，把DB扛住的部分前置
4. 限流：入口限流保护核心链路，非核心降级
5. 预案：扩容失败预案（镜像/配额预检）、DB连接数上限、AK/配额提前申请
6. 观测：大屏值班，QPS/错误率/DB水位
考点：定时+动态双弹性、配额是隐形杀手。', NULL, '[\"弹性\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 1, 'RDS（云数据库）相比自建 MySQL 的核心优势？', NULL, '[\"A. 自动备份/高可用/监控告警/内核维护全托管\",\"B. 一定更快\",\"C. 更便宜\",\"D. 无限制权限\"]', 'A。代价：部分超级权限受限（如不能改部分参数）、成本更高、锁定风险。', NULL, '[\"数据库\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'RDS 高可用版（主备）故障切换的特点？', NULL, '[\"A. 自动切换（约30s内），连接串不变（VIP漂移）\",\"B. 需人工改配置\",\"C. 数据丢失\",\"D. 永不切换\"]', 'A。应用不要直连 IP，一律用连接串/域名——为漂移与读写分离留路。', NULL, '[\"数据库\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '读多写少场景给 RDS 加读能力的标准做法？', NULL, '[\"A. 只读实例+代理层自动读写分离\",\"B. 主库直读\",\"C. 复制到自建\",\"D. 缓存就能解决一切\"]', 'A。注意复制延迟（写后读走主库）、只读实例单独计费与连接数评估。', NULL, '[\"数据库\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'RDS 的备份恢复能力通常包含？', NULL, '[\"A. 自动快照+binlog，支持 7 天内任意时间点恢复（PITR）\",\"B. 只能整库恢复\",\"C. 无备份\",\"D. 手动导出only\"]', 'A。误删库的救命稻草；克隆实例恢复（不影响生产）是主流操作。', NULL, '[\"数据库\",\"备份\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 1, '云负载均衡 CLB/SLB 的四层与七层监听区别？', NULL, '[\"A. 四层转发TCP/UDP连接；七层解析HTTP按域名/路径路由\",\"B. 只是端口不同\",\"C. 七层更快\",\"D. 无差别\"]', 'A。七层可做 HTTPS 卸载/灰度路由；四层性能高协议透传。', NULL, '[\"负载均衡\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'CLB 后端某台 ECS 健康检查失败会被？', NULL, '[\"A. 自动摘除流量，恢复后自动加回\",\"B. 报警人工处理\",\"C. 永久剔除\",\"D. 重启实例\"]', 'A。检查项设计：端口级 or HTTP级（更准）；间隔/阈值防抖动误摘。', NULL, '[\"负载均衡\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'CLB 会话保持（粘性会话）的实现方式？', NULL, '[\"A. 植入Cookie（负载均衡器写入）或源IP哈希\",\"B. 数据库存储\",\"C. 无法实现\",\"D. 只能HTTPS\"]', 'A。长期方案仍是应用无状态+集中Session（Redis），LB粘性只是过渡。', NULL, '[\"负载均衡\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '弹性伸缩（ESS/AS）的"冷却期"作用？', NULL, '[\"A. 扩缩容后一段时间内不再触发，防止指标抖动导致震荡\",\"B. 机器预热时间\",\"C. 计费周期\",\"D. 无用\"]', 'A。配合扩容预热（应用启动慢→加温计数）调参，否则会反复横跳。', NULL, '[\"弹性\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '弹性伸缩组缩容时如何选实例回收？', NULL, '[\"A. 按策略（最早创建/最贵配置），并保护关键实例\",\"B. 随机\",\"C. 最新\",\"D. 不会缩\"]', 'A。实例保护（Protection from scale-in）用于特殊任务机；配合生命周期钩子优雅下线（摘流量后释放）。', NULL, '[\"弹性\",\"进阶\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '云监控自定义指标的接入方式？', NULL, '[\"A. API/SDK 上报或 agent 插件（配合业务大盘与告警）\",\"B. 不支持\",\"C. 只能系统指标\",\"D. 手工录入\"]', 'A。业务指标（订单量/支付成功率）进云监控做告警是最直接的保障。', NULL, '[\"监控\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'RAM/IAM 子账号的核心原则？', NULL, '[\"A. 最小权限：按角色授权策略，禁用根账号日常操作\",\"B. 全给 AdministratorAccess\",\"C. 共用一个AK\",\"D. 只读\"]', 'A。人用子账号+MFA，程序用角色（STS临时凭证）而非长期 AK。', NULL, '[\"安全\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 3, 'AccessKey 泄漏（提交到 GitHub）的第一动作？', NULL, '[\"A. 立即禁用/轮换该AK（止损优先于排查）\",\"B. 删仓库就行\",\"C. 等下班处理\",\"D. 改密码\"]', 'A。泄漏到被扫描利用常在分钟级；随后审计 ActionTrail/CloudTrail 定位滥用、清持久化、复盘流程（pre-commit 扫描）。', NULL, '[\"安全\",\"应急\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'KMS（密钥管理服务）在应用侧的典型用法？', NULL, '[\"A. 加密存储敏感配置/信封加密，代码里不落明文密钥\",\"B. 存代码\",\"C. 存日志\",\"D. 管防火墙\"]', 'A。配合凭据管家轮换 DB 密码——密钥泄漏半径可控。', NULL, '[\"安全\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'WAF 部署在链路中的位置？', NULL, '[\"A. 流量入口（CLB 前/后），先过滤再进业务\",\"B. 数据库前\",\"C. 内网交换机\",\"D. 客户端\"]', 'A。防 OWASP Top10/CC；误拦截需白名单调优——上线前用观察模式。', NULL, '[\"安全\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'Terraform 的 state 文件作用？', NULL, '[\"A. 记录真实资源与声明的映射（增量变更与销毁依据）\",\"B. 日志\",\"C. 密码库\",\"D. 可有可无\"]', 'A。团队必须远端存储+状态锁（防并发写坏）；state 含敏感信息要控权。', NULL, '[\"IaC\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, 'Terraform 变更的正确流程？', NULL, '[\"A. 改代码 → plan 预览 → 评审 → apply → 记录\",\"B. 直接 apply\",\"C. 控制台改完补代码\",\"D. 只 plan\"]', 'A。plan 是变更预演，"控制台手改"会造成漂移（drift）——发现即收敛。', NULL, '[\"IaC\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 2, '函数计算/Serverless 适合的场景？', NULL, '[\"A. 事件驱动、短时、突发无状态任务（图片处理/ Webhook / 定时任务）\",\"B. 长连接高状态服务\",\"C. 数据库\",\"D. 全部替代\"]', 'A。冷启动与执行时长限制是主要约束；按调用计费对低频任务极省。', NULL, '[\"架构\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'CHOICE', 3, '多云（Multi-Cloud）的主要挑战？', NULL, '[\"A. API 不统一/网络互联/成本与监控双套/人才技能面\",\"B. 没有挑战\",\"C. 只贵\",\"D. 只慢\"]', 'A。缓解：K8s+Terraform 抹平部分差异；先问动机（议价/容灾/合规）再谈多云，别为多云而多云。', NULL, '[\"架构\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '自建 MySQL 迁到 RDS 的迁移方案与注意点？', NULL, NULL, '方案：DTS 数据传输服务（结构+全量+增量同步，割接前追平）。
注意点：1) 参数/字符集/时区对齐 2) 大表迁移与延迟监控 3) 割接窗口：停写→追平→改连接串→验证 4) 回退预案（反向同步）5) 权限差异（RDS 无 SUPER）导致的导入报错预处理。', NULL, '[\"数据库\",\"迁移\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '健康检查怎么配才算"真正可用"？', NULL, NULL, 'TCP检查只能证明端口开着（进程假死测不出）；生产用 HTTP 检查：轻量接口返回200+内容校验（版本号），间隔5s×2次不健康才摘。注意：健康检查地址不要触发重业务逻辑，避免"检查把服务压死"。', NULL, '[\"负载均衡\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '说一说"上云迁移 6R"策略。', NULL, NULL, 'Rehost 重新托管（ lift&shift 直接搬，最快）；Replatform 平台化小改造（换托管DB）；Repurchase 换 SaaS；Refactor 重构（云原生改造，收益最大成本最高）；Retire 退役（盘点发现没人用）；Retain 保留本地（合规/暂时）。先应用组合盘点分层定策略，别一刀切。', NULL, '[\"迁移\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '云上操作审计（ActionTrail/CloudTrail）的价值与用法？', NULL, NULL, '记录控制台/API 所有操作：谁在什么时候删了安全组/释放了实例。用法：1) 全量投递 OSS/日志服务长期留存 2) 关键操作告警（删除RDS、改安全组0.0.0.0/0）3) 事后取证（事故时间线）。配合"高危操作双人复核+变更单"形成闭环。', NULL, '[\"安全\",\"治理\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 2, '如何用标签（Tags）治理云资源？', NULL, NULL, '规范：强制标签键（env/project/owner/team），用策略/OPA 禁止无标签资源创建。用途：分账成本分析（按项目看账单）、批量运维（按标签选资源）、自动化（按 env 打安全基线）、权限边界。无标签=账单变成一笔糊涂账，是成本治理的地基。', NULL, '[\"成本\",\"治理\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 3, '设计"跨地域容灾"方案（应用+数据）。', NULL, NULL, '1. 流量：DNS 智能解析/GSLB 主备（健康检查自动切换）
2. 应用：B Region 常备最小规模（热备）或按需扩（温备），镜像/配置同步
3. 数据：RDS 跨地域同步（DTS）或定期快照复制（RPO 按业务定）；OSS 跨区域复制
4. 中间件：消息/缓存按业务级同步或接受丢失（明确 RPO）
5. 演练：季度级切换演练（切过去要能回来）
一句话：容灾买的是"演练过的切换能力"，不是配置。', NULL, '[\"架构\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'QA', 3, '什么是 FinOps？团队怎么起步？', NULL, NULL, 'FinOps=云成本的工程化治理（财务+技术协作）。起步三步：1) 可见性：标签分账+按团队/项目成本看板 2) 优化：闲置清理、计费模式匹配、规格右尺、存储分层 3) 运营：预算与异动告警、成本进架构评审（新方案必带成本项）、月度复盘。文化：让花钱的人看见成本。', NULL, '[\"成本\",\"体系\",\"高频\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 2, 'CLB 后端全部健康检查失败，但应用进程都在，怎么排查？', NULL, NULL, '1. 看检查配置：端口/路径对不对（应用监听 8080 检查配置成 80？）
2. 本机 curl 检查路径：404/500？应用改了路径没同步检查配置（高频）
3. 安全组：CLB 健康检查源 IP 是否被后端安全组拒绝（需放行 CLB 网段或 100.64/10）
4. 系统防火墙 conntrack/iptables
5. 应用假死：HTTP 检查超时——查线程池/DB
考点：健康检查源IP被安全组挡是经典盲区。', NULL, '[\"排障\",\"负载均衡\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 2, 'RDS 连接数打满（控制台告警），怎么处置与根治？', NULL, NULL, '应急：控制台/临时会话看 processlist（RDS 管理功能）→ KILL 空闲连接；临时调 max_connections（注意内存）。
排查：哪类连接（Sleep 堆积=应用连接池泄漏/配置错）；发布时间线对齐。
根治：应用侧连接池上限（所有实例总和<RDS上限×0.8）、只读实例分流、升级规格、Proxy 中间层。
云上加一条：多个环境共用一个 RDS 实例是常见爆因。', NULL, '[\"数据库\",\"应急\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 3, '弹性伸缩"该扩的时候扩不出来"，列出可能原因与预防。', NULL, NULL, '常见原因：1) 伸缩组最大实例数/账号配额到顶 2) 镜像不存在/被删（伸缩组引用旧镜像）3) 安全组/交换机 IP 耗尽（子网 /24 只剩3个IP）4) 启动模板参数失效（实例售罄/规格停售）5) 竞价实例价格超限全被回收
预防：伸缩组定期演练（手动触发展开）、配额巡检告警、镜像版本治理、多实例规格池+多可用区（降低售罄影响）。
考点：弹性没演练=没有弹性。', NULL, '[\"弹性\",\"实战\",\"必考\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置'),
(11, 'SCENARIO', 3, '公司要求核心系统做等保/安全基线整改，云上做什么？', NULL, NULL, '1. 账号：子账号+MFA+最小权限、AK 轮换、操作审计留存
2. 网络：安全组白名单化、VPC 分层、WAF+DDoS 基础防护
3. 主机：基线镜像（补丁/agent/日志）、漏洞扫描闭环
4. 数据：云盘/OSS 加密（KMS）、数据库审计、备份异地
5. 制度证据：变更审批/应急预案/演练记录（等保要材料）
用云厂商合规中心（配置审计规则集）自动巡检，人只处理例外。', NULL, '[\"安全\",\"合规\",\"实战\"]', 3, '[\"junior-ops\",\"devops\",\"sre\"]', '内置');
